var i=`1338-pollo-a-la-brasa`;var t=`world-1338`;var n=`PE`;var r=`south-america`;var o=4;var s=194;var l={en:`Pollo a la Brasa`,ua:`Польо а ла браса`};var g={en:`Pollo a la Brasa is a dish from Peru featuring whole chicken, garlic, light soy sauce, lime juice. This home-sized recipe records each ingredient at the step where it is used. Roasted home pollo a la brasa rather than true rotisserie chicken.`,ua:`Польо а ла браса, страва кухні країни Перу з такими основними складниками: ціла курка, часник, світлий соєвий соус, сік лайма. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Домашня курка запечена в духовці, а не на справжньому обертовому рожні.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 100 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 100 хвилин.`,t:[`marinating`],m:100,i:[[`whole-chicken`,1500,`g`],[`garlic`,6,`clove`],[`ground-cumin`,7,`g`],[`smoked-paprika`,8,`g`],[`light-soy-sauce`,70,`ml`],[`lime-juice`,65,`ml`]]},{en:`Roast the already seasoned food in a preheated oven until tender and safely cooked, using a thermometer for meat or poultry.`,ua:`Запікайте вже приправлені продукти в розігрітій духовці до м’якості та готовності, перевіряючи температуру м’яса термометром.`,t:[`roasting`],m:80,i:[]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:10,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`aji-amarillo-paste`,45,`g`],[`mayonnaise`,120,`g`]]}];var m={slug:i,id:t,country:`PE`,region:r,servings:4,minutes:194,title:l,text:g,steps:h};export{n as country,m as default,t as id,s as minutes,r as region,o as servings,i as slug,h as steps,g as text,l as title};